        // Total supply should have decreased due to burning
        assertLt(finalTotalSupply, initialTotalSupply, "Total supply should have decreased due to burn");

        // The burn should be significant
        // With our fee settings: 100% burn fee means all liquidity fees go to burn
        // Total fees = 100/1000 = 10% of transfer amount
        // All of this (100% of fees) goes to burn
        uint256 expectedBurn = transferAmount * 100 / 1000; // 10% of transfer amount
        console.log("Expected burn (10% of transfer):", expectedBurn);
        console.log("Actual burn:", totalSupplyDecrease);

        // The oracle checks if attacker balance increased
        // In this case, we demonstrate the vulnerability by showing total supply diversion
        // The attacker's balance decreased due to transfer, but the system state is now inconsistent
        // This inconsistency can be exploited for profit in subsequent steps
    }






